'use strict';
const $=s=>document.querySelector(s);
const $$=s=>Array.from(document.querySelectorAll(s));
let modalReturn=null,toastTimer=null,tooltipTimer=null;
const btn=(text,action,style='',ic='',attrs='')=>`<button type="button" class="btn ${style}" data-action="${action}" ${attrs}>${ic?icon(ic,17):''}${text}</button>`;
const badge=(text,type='')=>`<span class="badge ${type}"><i class="dot"></i>${text}</span>`;
function statusBadge(){const s=hotel().stage;return badge(s==='active'?'Активен':s==='paused'?'Приостановлен':'Подключение',s==='active'?'good':s==='paused'?'error':'pending');}
function art(index=0,sketch=false,custom=''){return `<div class="room-art a${index%3} ${sketch?'sketch':''} ${custom?'custom':''}" ${custom?`style="background-image:url('${esc(custom)}')"`:''} role="img" aria-label="${sketch?'Скетч':'Фотография'} демонстрационного номера"></div>`;}
const note=(text,type='',ic='Info')=>`<div class="note ${type}">${icon(ic,19)}<div>${text}</div></div>`;
const head=(title,desc='',actions='',eyebrow='Экстранет отеля')=>`<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div>${actions?`<div class="head-actions">${actions}</div>`:''}</div>`;
function field(label,key,value,options={}){const {type='text',required=false,disabled=false,select=null,full=false,hint='',placeholder=''}=options;return `<div class="field ${full?'full':''} ${required&&!disabled&&!String(value||'').trim()?'required-field':''}" data-field="${key}"><label for="f-${key}">${label}${required?' <span class="req">*</span>':''}</label>${select?`<select id="f-${key}" name="${key}" ${disabled?'disabled':''} ${required?'required':''}>${select.map(x=>`<option ${x===value?'selected':''} value="${esc(x)}">${esc(x)}</option>`).join('')}</select>`:type==='textarea'?`<textarea id="f-${key}" name="${key}" ${disabled?'disabled':''}>${esc(value)}</textarea>`:`<input id="f-${key}" name="${key}" type="${type}" value="${esc(value)}" placeholder="${esc(placeholder)}" ${disabled?'disabled':''} ${required?'required':''}>`}${hint?`<div class="hint">${hint}</div>`:''}<div class="error-text" hidden></div></div>`;}
function shell(){const h=hotel(),n=h.notifications.filter(n=>!n.read).length;const route=view.route.split('/')[0];return `${view.mobile?'<div class="side-scrim" data-action="mobile-close"></div>':''}<aside class="sidebar ${view.mobile?'open':''}"><a href="#overview" class="brand" aria-label="Hopinn — главная"><img src="assets/logo/hopinn-logo-white.svg" alt="Hopinn"><span>Экстранет</span></a><nav class="nav" aria-label="Главная навигация"><a class="${['overview','connection'].includes(route)?'selected':''}" href="#overview">${icon('LayoutDashboard',19)}Подготовка к запуску${!h.everActive?'<i class="dot"></i>':''}</a><div class="nav-caption">Управление отелем</div>${[['hotel','Building2','Отель'],['rooms','BedDouble','Номера и тарифы'],['calendar','CalendarDays','Доступность и цены'],['bookings','ClipboardList','Бронирования'],['statements','FileText','Акты и сверки']].map(([r,ic,label])=>`<a href="#${r==='hotel'?'hotel/general':r}" class="${route===r||(r==='rooms'&&route==='rates')?'selected':''}">${icon(ic,19)}${label}${!h.everActive&&isCabinetOpen()&&getChecks().some(c=>!c.done&&((r==='hotel'&&c.route.startsWith('hotel/'))||(r==='rooms'&&['rooms','rates'].includes(c.route))))?'<span class="nav-missing" aria-label="Есть обязательные незаполненные данные"></span>':''}</a>`).join('')}<a href="#profile" class="mobile-only">${icon('CircleUserRound',19)}Мой профиль</a></nav><div class="sidebar-bottom"><a class="support-link" href="mailto:hotel_support@hopinn.ru">${icon('CircleHelp',18)}Помощь бэкофиса</a><div class="prototype-label"><i class="dot"></i>Прототип · демоданные</div></div></aside><header class="topbar"><button class="icon-btn mobile-menu" data-action="mobile" aria-label="Открыть меню">${icon('Menu')}</button><div class="hotel-select"><div class="hotel-avatar">${icon('Hotel',21)}</div><div><select aria-label="Выбранный отель" id="hotel-switch">${state.hotels.map(x=>`<option value="${x.id}" ${x.id===h.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select><div class="hotel-meta">ID ${h.id} · Санкт-Петербург</div></div></div>${statusBadge()}<span class="spacer"></span><button class="icon-btn" data-action="notifications" aria-label="Уведомления${n?', '+n+' непрочитанных':''}">${icon('Bell',21)}${n?`<span class="notification-count">${n}</span>`:''}</button><div class="top-divider"></div><button class="user-btn" data-action="profile"><div class="avatar">АВ</div><div class="user-text"><strong>${esc(state.user.name)}</strong><small>${esc(state.user.email)}</small></div>${icon('ChevronDown',14)}</button></header><main class="main" id="main" tabindex="-1"><div class="mobile-status">${statusBadge()}</div><div class="page-content">${renderPage()}</div><footer class="foot"><span>© 2026 Hopinn · Экстранет отеля</span><a href="mailto:hotel_support@hopinn.ru">hotel_support@hopinn.ru ${icon('ArrowUpRight',11)}</a></footer></main><button class="demo-trigger" data-action="demo">${icon('SlidersHorizontal',14)}Сценарии прототипа</button>`;}
function render(){if(view.route==='hotel/staff'&&!roleAdmin())view.route='hotel/general';$('#app').innerHTML=shell();bindLocal();}
function go(route){hideTooltip();closeOverlay();view.mobile=false;view.route=route;if(location.hash!==`#${route}`)location.hash=route;else render();window.scrollTo({top:0,behavior:'instant'});}
window.addEventListener('hashchange',()=>{hideTooltip();closeOverlay();view.mobile=false;view.route=location.hash.slice(1)||'overview';render();window.scrollTo({top:0,behavior:'instant'});});
function renderPage(){const r=view.route;if(!isCabinetOpen()&&!['connection','profile'].includes(r))return connection();if(r==='overview')return overview();if(r==='connection')return connection();if(r.startsWith('hotel'))return hotelPage();if(r==='rooms'||r==='rates')return roomsPage();if(r==='calendar')return calendarPage();if(r==='profile')return profilePage();if(r==='bookings'||r==='statements')return outOfScope(r);return overview();}
function overview(){const h=hotel(),checks=getChecks(),done=checks.filter(x=>x.done).length,complete=done===checks.length;let hero='',aside='';
 if(h.stage==='setup'||h.stage==='fixes'){hero=`<section class="overview-hero"><div><div class="tiny" style="color:#e4d5ef;margin-bottom:9px">${h.stage==='fixes'?'Требуются исправления':'До первых гостей — несколько шагов'}</div><h2>${complete?'Всё готово к проверке':'Подготовим ваш отель к запуску'}</h2><p>${complete?'Отправьте данные бэкофису. Мы проверим настройки и подготовим карточку отеля.':'Мы уже получили часть данных из TravelLine. Проверьте сведения и завершите настройку.'}</p>${btn(complete?'Отправить на модерацию':'Продолжить настройку',complete?'submit-review':'continue','primary','ArrowRight')}</div><div class="progress-ring" style="--progress:${done/checks.length*100}%"><div><strong>${done}<span style="font-size:17px;font-weight:500"> / ${checks.length}</span></strong><small>шагов готово</small></div></div></section>`;if(h.stage==='fixes')hero+=note(`<strong>Замечания бэкофиса</strong><p>${esc(h.boNotes)}</p>`,'warning','CircleAlert');}
 else if(h.stage==='review'){hero=`<section class="overview-hero"><div><div class="tiny" style="color:#e4d5ef;margin-bottom:9px">На модерации</div><h2>Отель на проверке у бэкофиса</h2><p>Проверяем данные и TravelLine, готовим скетчи и описание. Сообщим об активации в кабинете и по email.</p>${btn('Посмотреть данные','go:hotel/general','outline','Eye')}</div><div class="progress-ring" style="--progress:100%"><div>${icon('Clock3',40)}</div></div></section>`;}
 else if(h.stage==='paused'){hero=`<div class="card mb">${note('<strong>Работа отеля приостановлена</strong><p>Обнаружено несоответствие цены тарифа Hopinn 40%. Новые продажи остановлены. После исправления бэкофис возобновит работу.</p>','error','CircleAlert')}<div class="mt-sm">${btn('Посмотреть проблему','go:connection','primary','ArrowRight')}</div></div>`;}
 else {hero=`<section class="overview-hero"><div><div class="tiny" style="color:#e4d5ef;margin-bottom:9px">Проверки пройдены · Отель активен</div><h2>${h.emptyInventory?'Отель готов. Ждём открытый фонд':'Ваш отель готов принимать гостей'}</h2><p>${h.emptyInventory?'Сейчас нет доступных предложений. Откройте фонд в TravelLine — предложения появятся без повторной активации.':'Доступность, цены и квоты поступают из TravelLine. Здесь можно проверить, что увидят гости.'}</p>${btn('Посмотреть календарь','go:calendar','primary','CalendarDays')}</div><div class="progress-ring" style="--progress:100%"><div>${icon('Check',40)}</div></div></section>`;}
 aside=`<aside class="stack overview-aside"><section class="card"><div class="side-photo">${art(0,true)}</div><div class="section-label">Карточка вашего отеля</div><h3 style="margin-top:10px">Интрига с первого взгляда</h3><p class="muted tiny mt-sm">Гость увидит скетч, удобства и рейтинг. Название и оригинальные фотографии откроются после оплаты.</p><div class="mt">${btn(h.contentReady?'Открыть предпросмотр':'Как выглядит карточка','go:hotel/preview','outline small','ArrowUpRight')}</div></section><section class="card"><div class="flex">${icon('PlugZap',20)}<h3>Связь с TravelLine</h3></div><div class="mt-sm">${badge(h.connected?'Подключено':'Ожидаем подключение',h.connected?'good':'warn')}</div><p class="tiny muted mt-sm">${h.connected?'Последнее обновление: '+esc(h.updated):'Откройте канал Hopinn в кабинете TravelLine.'}</p><button class="text-link mt-sm tiny" data-action="go:connection">Настройки подключения ${icon('ChevronRight',14)}</button></section></aside>`;
 return head('Ваш отель в Hopinn',h.everActive?'Всё важное о работе отеля — в одном месте.':'Проверьте сведения. Подготовку скетчей и запуск мы возьмём на себя.',btn('Предпросмотр карточки','go:hotel/preview','outline optional','Eye'))+hero+`<div class="overview-grid ${h.stage==='fixes'?'mt':''}"><div><section class="card"><div class="between"><div><h2>${h.everActive?'Настройки отеля':'Подготовка отеля'}</h2><p class="card-subtitle">${h.everActive?'Сведения, контент и подключение':'Заполненные данные сразу доступны в разделах кабинета'}</p></div>${badge(done+' из '+checks.length,'pending')}</div><div class="checklist">${checks.map((c,i)=>`<div class="check-row" role="link" tabindex="0" data-action="go:${c.route}"><div class="check-circle ${c.done?'done':'required-missing'}">${c.done?icon('Check',17):i+1}</div><div><h3>${c.name}</h3><p>${c.detail}</p></div><span class="spacer"></span>${c.done?badge('Готово','good'):badge('Нужно заполнить','error')}${icon('ChevronRight',17)}</div>`).join('')}</div></section><div class="mt">${note(h.stage==='review'?'Можно продолжать редактировать данные во время проверки. Бэкофис увидит изменения.':h.everActive?'Изменить описание, условия или фотографии можно через бэкофис. Цены и фонд обновляйте в TravelLine.':'После отправки бэкофис проверит данные и подключение, подготовит скетчи и описание, затем активирует отель.','',h.everActive?'Info':'ShieldCheck')}</div></div>${aside}</div>`;
}
function connection(){
 const h=hotel(),opened=isCabinetOpen(),checks=getAutoChecks();
 return head(opened?'Подключение и проверки':'Подключите TravelLine','Получите категории и тарифы, чтобы начать заполнение кабинета.',h.connected?btn('Обновить данные','sync','outline','RefreshCw'):btn('Я подключил канал','connect','primary','Check'))+
 `<div class="form-layout"><div class="stack"><section class="card"><div class="between"><div><h2>Канал Hopinn в TravelLine</h2><p class="card-subtitle">Объект ${h.id} · ${esc(h.name)}</p></div>${badge(h.connected?(h.stale?'Данные устарели':'Подключено'):'Ожидаем данные',h.connected&&!h.stale?'good':'warn')}</div>${!opened?`<ol class="connection-steps"><li>Откройте канал Hopinn в кабинете TravelLine.</li><li>Предоставьте доступ к категориям и тарифам.</li><li>После получения справочников проверьте предзаполненные сведения и выполните сопоставления здесь.</li></ol>${note('Профиль, переключение отелей и помощь доступны уже сейчас. Формы отеля откроются после первого получения данных.','warning','PlugZap')}`:!h.connected?`<div class="mt">${note('Связь временно недоступна. Кабинет остаётся открытым, но актуальные данные и результаты проверок пока неизвестны.','warning')}</div>`:`<div class="read-value mt"><span>Последнее получение данных</span><strong>${esc(h.updated)}</strong></div><div class="read-value"><span>Категории / тарифы</span><strong>${h.rooms.length} / ${h.rates.length}</strong></div>`}${opened?`<div class="mt">${btn('Продолжить подготовку','go:overview','outline','ArrowRight')}</div>`:''}</section>
 <section class="card"><h2>Результаты проверок</h2><p class="card-subtitle">Обновляются при получении данных и изменении настроек</p><div class="status-list mt-sm">${checks.map(c=>`<div class="status-item check-result">${icon(c.status==='Проверено'?'CircleCheck':c.status==='Есть ошибка'?'CircleAlert':'Clock3',18)}<div><strong>${esc(c.name)}</strong><p class="tiny muted mt-sm">${esc(c.detail||'')}</p><small class="muted">${esc(c.checkedAt)}</small></div>${badge(c.status,c.status==='Проверено'?'good':c.status==='Есть ошибка'?'error':'pending')}</div>`).join('')}</div></section></div><aside class="stack"><div class="help-card">${icon('ShieldCheck',22)}<h3>Решение об активации — за бэкофисом</h3><p>БО проверит договор, сведения ФСА и качество контента. Успешные автоматические проверки сами отель не активируют.</p><p>Для отправки на модерацию достаточно обязательных данных, фото и сопоставлений. Подготовка скетчей не блокирует отправку.</p></div><div class="help-card"><h3>Все размещения проверяются</h3><p>Проверки охватывают взрослых, детей и дополнительные места. Фильтр взрослых в календаре ограничивает только его отображение.</p></div></aside></div>`;
}
function photosPage(){const h=hotel();return `<div class="between mb"><div><h2>Фотографии для скетчей</h2><p class="card-subtitle">От 3 до 5 фото номеров · ${h.photos.filter(p=>p.kind==='room').length} загружено</p></div>${canEdit()?btn('Выбрать из TravelLine','tl-photos','outline','Images'):''}</div><div class="mb">${note('Добавьте 3–5 фото номеров самой простой или следующей по уровню категории из тех, что предлагаете в Hopinn. По ним мы подготовим скетчи для карточки отеля.','', 'Image')}</div><div class="photo-grid">${photoCards('room')}${canEdit()&&h.photos.filter(p=>p.kind==='room').length<5?uploadTile('room'):''}</div><div class="between mt mb"><div><h2>Общие фотографии отеля</h2><p class="card-subtitle">Необязательно · до 3 фото · показываются только после раскрытия</p></div></div><div class="photo-grid">${photoCards('general')}${canEdit()&&h.photos.filter(p=>p.kind==='general').length<3?uploadTile('general'):''}</div>${!canEdit()?`<div class="mt">${note('Для замены фотографий напишите бэкофису: мы также обновим связанные скетчи.','', 'Mail')}</div>`:''}<input type="file" accept="image/*" multiple id="photo-file" hidden>`;}
function uploadTile(kind){return `<button type="button" class="upload-tile" data-action="upload:${kind}">${icon('Upload',24)}<strong>Загрузить фотографии</strong><small>Выберите файлы на устройстве</small></button>`;}
function photoCards(kind){return hotel().photos.filter(p=>p.kind===kind).map(p=>`<article class="photo-card"><div class="photo">${art(p.asset,false,p.url)}${canEdit()?`<button class="icon-btn" style="right:44px" data-action="replace-photo:${p.id}" aria-label="Заменить фото ${esc(p.name)}">${icon('RefreshCw',14)}</button><button class="icon-btn" data-action="remove-photo:${p.id}" aria-label="Удалить фото ${esc(p.name)}">${icon('Trash2',14)}</button>`:''}</div><div class="photo-info"><strong>${esc(p.name)}</strong><small>${esc(p.source)} · ${kind==='room'?'Для скетча':'После раскрытия'}</small></div></article>`).join('');}
function contentPage(){
 const h=hotel(),pairs=validSketches(),pair=pairs[view.photoIndex%Math.max(1,pairs.length)],photo=pair&&h.photos.find(p=>p.id===pair.photoId);
 return `${!h.contentReady?`<div class="mb">${note('Бэкофис готовит материалы по вашим исходным данным. Если оригинал заменён, связанный скетч должен быть проверен заново.','warning','Clock3')}</div>`:''}<div class="between mb"><div><h2>Оригинал и скетч</h2><p class="card-subtitle">Каждый скетч связан с конкретной фотографией отеля.</p></div>${badge(h.contentReady?'Подготовлено бэкофисом':'В подготовке',h.contentReady?'good':'pending')}</div><div class="content-grid"><section>${pair?`<div class="compare" style="--split:50%" data-photo-id="${esc(photo.id)}"><div class="layer">${art(pair.asset,true)}</div><div class="layer original">${art(photo.asset,false,photo.url)}</div><span class="compare-label left">Оригинальная фотография</span><span class="compare-label right">Скетч</span><div class="divider"><b>${icon('MoveHorizontal',20)}</b></div><input aria-label="Сравнение оригинала и скетча" id="compare-range" type="range" min="0" max="100" value="50"></div><div class="thumb-row">${pairs.map((p,i)=>`<button class="thumb ${pair.id===p.id?'active':''}" data-action="sketch:${i}" aria-label="Скетч ${i+1}">${art(p.asset,true)}</button>`).join('')}</div><p class="tiny muted mt-sm">${pairs.length} скетча · источник: ${esc(photo.name)}</p>`:`<div class="card empty-state">${icon('Images',32)}<h3>Скетчи ещё не готовы</h3><p>Здесь появятся обработанные фотографии и сравнение с оригиналами после подготовки бэкофисом.</p></div>`}</section><section class="card"><div class="section-label">Описание для гостя</div>${h.contentReady?`<h3 class="mt-sm">Спокойный отдых в центре города</h3><p class="tiny muted mt-sm">Камерный городской отель со светлыми номерами и внимательным сервисом. Подойдёт для выходных в Петербурге и деловой поездки.</p>${h.ratingsAvailable?`<div class="flex mt"><span class="rating">9,1</span><div><strong>Превосходно</strong><p class="tiny muted">На основе 248 отзывов</p></div></div><p class="review-quote mt">Гости отмечают удобные кровати, чистоту и доброжелательность сотрудников. В отдельных отзывах упоминаются небольшие номера.</p><p class="tiny muted">Демонстрационные рейтинг и отзывы.</p>`:`<p class="tiny muted mt">Достоверные рейтинг и отзывы не предоставлены. В клиентской карточке эти блоки скрыты.</p>`}`:`<p class="muted mt">Описание и материалы карточки готовит бэкофис.</p>`}</section></div><div class="grid-two mt"><section class="card"><h3>Ориентиры</h3><div class="read-value"><span>Район</span><strong>Центральный</strong></div><div class="read-value"><span>Метро</span><strong>В пешей доступности</strong></div><p class="tiny muted">БО проверяет анонимность описания и ориентиров.</p></section><section class="help-card"><h3>Заметили ошибку?</h3><p>Сообщите бэкофису. Скетчи, описание и рейтинг доступны для просмотра.</p><a class="text-link" href="mailto:hotel_support@hopinn.ru">hotel_support@hopinn.ru</a></section></div>`;
}
function guestAmenities(){const h=hotel();return SERVICE_LIST.filter(([id])=>h.services[id]&&h.services[id]!=='Нет').map(([id,name,ic])=>`<span class="chip">${icon(ic,14)}${esc(name)} · ${esc(h.services[id].toLowerCase())}${['early','late'].includes(id)?' · при наличии возможности':''}</span>`).join('');}
function previewPage(){
 const h=hotel(),pairs=validSketches(),pair=pairs[view.photoIndex%Math.max(1,pairs.length)],original=pair&&h.photos.find(p=>p.id===pair.photoId),f=h.form;
 if(!pair||!h.contentReady)return `<section class="card empty-state">${icon('Image',30)}<h2>Карточка в подготовке</h2><p>После подготовки материалов бэкофисом здесь появится предпросмотр до и после раскрытия отеля.</p>${btn('Посмотреть исходные фотографии','go:hotel/photos','outline')}</section>`;
 const body=`<div class="stars">★★★★</div><div class="between mt-sm"><h3>Гостиница <span class="hotel-name-mask" aria-hidden="true"></span></h3>${h.ratingsAvailable?'<span class="rating">9,1</span>':''}</div><p class="tiny muted mt-sm">Санкт-Петербург · Центральный район</p><p class="tiny muted mt-sm">Название откроется после оплаты</p>`;
 let preview;
 if(view.preview==='search')preview=`<article class="guest-card"><div class="guest-photo">${art(pair.asset,true)}</div><div class="guest-body">${body}<div class="flex mt"><span class="discount">−40%</span><s class="tiny muted">10 000 ₽</s></div><div class="mt-sm"><span class="guest-price">6 000 ₽</span> <span class="tiny">за ночь · 2 взрослых</span></div>${btn('Посмотреть отель','preview:hidden','primary','ArrowRight')}</div></article>`;
 else if(view.preview==='hidden')preview=`<article class="guest-page"><div class="guest-photo">${art(pair.asset,true)}</div><div class="guest-body">${body}<p class="muted tiny mt">Светлые номера, спокойные интерьеры и внимательный сервис.</p><div class="guest-amenities">${guestAmenities()}</div><div class="read-value mt"><span>Стандарт · 2 взрослых</span><strong id="preview-room-price">6 000 ₽ / ночь</strong></div><label class="field mt-sm">Тип кровати<select id="preview-bed"><option>Одна большая кровать</option><option>Две односпальные</option></select></label><p class="tiny muted mt-sm">Пожелания можно написать в общем комментарии при оформлении. Их выполнение не гарантируется.</p><p class="tiny muted mt-sm">Предпросмотр: бронирование здесь не оформляется.</p></div></article>`;
 else preview=`<article class="guest-page"><div class="guest-photo" data-original-id="${esc(original.id)}">${art(original.asset,false,original.url)}</div><div class="guest-body"><div class="stars">★★★★</div><h2 class="mt-sm">${esc(h.name)}</h2><p class="tiny muted mt-sm">Демонстрационный отель · Санкт-Петербург</p>${[['Адрес',f.address],['Телефон',f.phone],['Email',f.email],['Сайт',f.website],['Заезд / выезд',f.checkin+' / '+f.checkout],['Стойка регистрации',f.reception==='Круглосуточно'?f.reception:f.receptionHours],...(f.reception!=='Круглосуточно'?[['Заселение вне часов',f.outsideArrival],['Предварительное согласование',f.advanceArrival]]:[]),...(f.deposit==='Требуется'?[['Страховой депозит',[f.depositAmount,f.depositNotes].filter(Boolean).join(' · ')||'Условия уточняются']]:f.deposit==='Не требуется'?[['Страховой депозит','Не требуется']]:[]),...(f.petsConditions&&h.services.pets!=='Нет'?[['С животными',f.petsConditions]]:[]),...(f.conditions?[['Важные условия',f.conditions]]:[])].map(([label,val])=>`<div class="read-value"><span>${label}</span><strong>${esc(val||'Не указано')}</strong></div>`).join('')}<div class="guest-amenities">${guestAmenities()}</div>${h.photos.filter(p=>p.kind==='general').length?`<h3 class="mt">Фотографии отеля</h3><div class="photo-grid mt-sm">${h.photos.filter(p=>p.kind==='general').map(p=>`<div class="photo" style="height:120px">${art(p.asset,false,p.url)}</div>`).join('')}</div>`:''}</div></article>`;
 return `<div class="between mb"><div><h2>Глазами гостя</h2><p class="card-subtitle">Закрытый предпросмотр для сотрудников отеля</p></div>${btn('Другой скетч','rotate-sketch','outline small','RefreshCw')}</div><div class="segmented">${[['search','Карточка в выдаче'],['hidden','До раскрытия'],['revealed','После раскрытия']].map(([id,label])=>`<button class="${view.preview===id?'active':''}" data-action="preview:${id}">${label}</button>`).join('')}</div><div class="preview-stage">${preview}</div>`;
}
function staffPage(){if(!roleAdmin())return '';return `<div class="between mb"><div><h2>Команда отеля</h2><p class="card-subtitle">Управляйте доступом только к этому отелю</p></div>${btn('Пригласить сотрудника','invite','primary','Plus')}</div><section class="card table-card"><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Сотрудник</th><th>Должность</th><th>Роль</th><th>Доступ</th><th>Последний вход</th><th></th></tr></thead><tbody>${hotel().staff.map(u=>`<tr><td><strong>${esc(u.name)}</strong><small>${esc(u.email)}</small></td><td>${esc(u.job||'—')}</td><td>${esc(u.role)}</td><td>${badge(esc(u.status),u.status==='Активен'?'good':u.status==='Приглашён'?'pending':'')}</td><td class="nowrap tiny muted">${esc(u.last)}</td><td><button class="icon-btn" data-action="staff:${u.id}" aria-label="Настройки сотрудника ${esc(u.name)}">${icon('Settings2',16)}</button></td></tr>`).join('')}</tbody></table></div></section><div class="mt">${note('У каждого сотрудника — свой аккаунт. Последнего действующего администратора нельзя лишить доступа до принятия приглашения его заменой.','', 'Users')}</div>`;}
function roomsPage(){const rates=view.route==='rates',h=hotel();return head('Номера и тарифы','Вы сопоставляете категории и тарифы. Бэкофис проверяет результат.',btn('Подключение TL','go:connection','outline','PlugZap'))+`<nav class="tabs" aria-label="Настройки номеров и тарифов"><button class="tab ${!rates?'active':''}" data-action="go:rooms">Категории номеров <span class="pill-count">${h.rooms.length}</span></button><button class="tab ${rates?'active':''}" data-action="go:rates">Назначения тарифов <span class="pill-count">${requiredRateRoles().length}</span></button></nav>`+(rates?ratesPage():categoriesPage());}
function categoriesPage(){const h=hotel(),active=h.rooms.filter(r=>r.participating!==false),done=active.filter(r=>r.class&&r.bed).length;return `<div class="between mb"><div><h2>Категории из TravelLine</h2><p class="card-subtitle">Выберите участвующие категории; весь фонд подключать не нужно.</p></div>${badge(done+' из '+active.length+' сопоставлены',done===active.length&&active.length?'good':'error')}</div><section class="card table-card"><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Порядок</th><th>Категория TravelLine</th><th>Размещение</th><th>Категория Hopinn</th><th>Состояние</th><th></th></tr></thead><tbody>${h.rooms.map((r,i)=>`<tr class="room-row"><td><div class="order-buttons">${btn('↑','room-up:'+r.id,'outline small','',i===0?'disabled aria-label="Выше"':'aria-label="Выше"')}${btn('↓','room-down:'+r.id,'outline small','',i===h.rooms.length-1?'disabled aria-label="Ниже"':'aria-label="Ниже"')}</div></td><td class="category-name"><strong>${esc(r.name)}</strong><small>${r.area??'Не указано'} м² · ID ${r.id}</small></td><td>${r.main??'Не указано'} осн. · ${r.extra??'Не указано'} доп.<small>${esc(r.beds||'Не указано')}</small></td><td><strong>${esc(r.class||'Не выбрана')}</strong><small>${esc(r.bed||'Требуется сопоставление')}</small></td><td>${badge(r.participating===false?'Не участвует':r.class&&r.bed?'Сопоставлено':'Нужно сопоставить',r.participating===false?'':r.class&&r.bed?'good':'error')}</td><td>${btn('Открыть','room:'+r.id,'outline small','Settings2')}</td></tr>`).join('')}</tbody></table></div></section><div class="mt">${note('Порядок в списке применяется только при одинаковой цене и существенных условиях среди подходящих по категории, кроватям и размещению предложений. Первоначально категории идут в порядке добавления.')}</div><div class="grid-two mt"><section class="help-card"><h3>Один класс — разные кровати</h3><p>Клиент выбирает класс и гарантированный вариант кровати. Если тип не гарантирован, пожелание можно написать в общем комментарии к бронированию.</p></section><section class="help-card"><h3>Параметры получены из TL</h3><p>Вместимость, детские и дополнительные места здесь доступны только для просмотра. Цены зависят от дат, тарифа и состава гостей.</p></section></div>`;}
function ratesPage(){const h=hotel(),roles=requiredRateRoles(),done=getChecks().find(c=>c.id==='rates').done;return `<div class="between mb"><div><h2>Назначения тарифов</h2><p class="card-subtitle">Основной без завтрака — база сравнения. Специальные тарифы — для продажи.</p></div>${badge(done?roles.length+' назначений готовы':'Проверьте назначения',done?'good':'error')}</div><p class="mb tiny muted">${h.breakfastSold?'Завтрак продаётся: для каждого уровня скидки сопоставьте пару с завтраком и без него.':'Завтрак не продаётся: достаточно основного и трёх специальных тарифов без завтрака.'}</p><form id="rates-form"><section class="card table-card"><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Тариф TravelLine</th><th>Назначение в Hopinn</th><th>Использование</th></tr></thead><tbody>${h.rates.map(r=>`<tr><td><strong>${esc(r.name)}</strong><small>ID ${r.id}</small></td><td><select class="select ${!r.role?'required-field':''}" name="rate-${r.id}" aria-label="Назначение ${esc(r.name)}"><option value="">Не участвует / не выбрано</option>${roles.map(role=>`<option ${r.role===role?'selected':''}>${role}</option>`).join('')}</select></td><td class="muted">${r.role.startsWith('Основной')?'База сравнения':r.role?'Продажи со скидкой':'Не участвует'}</td></tr>`).join('')}</tbody></table></div></section><div class="mt">${note('<strong>Завтраки уже включены в соответствующий тариф</strong><p>Стоимость для клиента — разница сопоставимых специальных тарифов с учётом сервисного сбора. Она одинакова на уровнях 30%, 40% и 50% при одинаковом размещении. Повторно к цене тарифа завтрак не прибавляется.</p>','', 'Coffee')}</div><div class="between mt"><span id="rates-error" class="error-text"></span><button type="submit" class="btn primary">Сохранить назначения</button></div></form>`;}
function cellData(roomIndex,d,discount,breakfast=false){
 const h=hotel(),r=h.rooms[roomIndex],adults=Number(view.calendarAdults||2),seed=d+view.calendarOffset;
 const unsupported=!(r.adultOptions||[]).includes(adults),baseQuote=r.pricesByAdults?.[adults];
 const base=unsupported||baseQuote==null?null:baseQuote+((seed%7+7)%7>=4?1200:0),K=(h.serviceFee??13)/100;
 const stale=h.stale||!h.connected,unknown=stale||base==null;
 const guestBreakfast=breakfast?(r.breakfastByAdults?.[adults]??null):0;
 const noStock=h.emptyInventory||seed%11===7,closed=noStock||(seed%9===2&&discount===50)||(breakfast&&seed%9===5);
 const hotelRoom=base==null?null:base*(1-discount/100)*(1-K),hotelBreakfast=guestBreakfast==null?null:guestBreakfast*(1-K);
 const totalHotel=hotelRoom==null||hotelBreakfast==null?null:hotelRoom+hotelBreakfast;
 return {base,guest:totalHotel==null?null:totalHotel/(1-K),hotel:totalHotel,guestBreakfast,hotelBreakfast,discount,full:discount+(h.serviceFee??13)*(1-discount/100),closed,noStock,stale:unknown||guestBreakfast==null,unsupported,breakfast,adults,minLos:seed%7===3||seed%7===4?2:1,inventory:noStock?0:Math.max(1,7-(Number(r.id)%100-1)-Math.abs(seed)%4)};
}
function dateAt(n){return new Date(2026,10,2+view.calendarOffset+n);}
function calendarPage(){
 const h=hotel(),dates=Array.from({length:10},(_,i)=>dateAt(i)),adults=Number(view.calendarAdults||2),rooms=h.rooms.filter(r=>r.participating!==false&&r.class&&r.bed);
 const range=dates[0].toLocaleDateString('ru-RU',{day:'numeric',month:'short'})+' — '+dates[9].toLocaleDateString('ru-RU',{day:'numeric',month:'short',year:'numeric'});
 const rows=[30,40,50].flatMap(d=>(h.breakfastSold?[false,true]:[false]).map(bb=>({d,bb,role:`Hopinn ${d}% — ${bb?'с завтраком':'без завтрака'}`}))).filter(x=>h.rates.some(r=>r.role===x.role));
 return head('Доступность и цены','Просмотр предложения для Hopinn. Цены и фонд меняются в TravelLine.',btn('Обновить данные','sync','outline','RefreshCw'))+
 `${h.stage==='paused'?`<div class="mb">${note('Отель приостановлен. Цены показаны для проверки; новые продажи закрыты.','error')}</div>`:''}${h.stale||!h.connected?`<div class="mb">${note('Актуальные данные недоступны. Остаток неизвестен, это не означает отсутствие мест.','warning')}</div>`:''}
 <div class="calendar-top"><div class="flex"><button class="icon-btn btn outline" data-action="calendar-prev" aria-label="Предыдущие даты">${icon('ChevronLeft',18)}</button><h2>${range}</h2><button class="icon-btn btn outline" data-action="calendar-next" aria-label="Следующие даты">${icon('ChevronRight',18)}</button></div><div class="calendar-filters"><label>Взрослые на основных местах<select class="select" id="calendar-adults" aria-label="Количество взрослых">${[1,2,3].map(n=>`<option value="${n}" ${n===adults?'selected':''}>${n} ${n===1?'взрослый':'взрослых'}</option>`).join('')}</select></label><label>Категории<select class="select" id="calendar-filter" aria-label="Категория номера"><option value="all">Все категории</option>${rooms.map(r=>`<option value="${r.id}" ${view.calendarFilter===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select></label>${btn('Сегодня','calendar-today','outline small')}</div></div>
 <div class="calendar-wrap"><table class="calendar"><thead><tr><th>Категория / тариф<br>${adults} ${adults===1?'взрослый':'взрослых'} · основные места</th>${dates.map((d,i)=>`<th class="${[0,6].includes(d.getDay())?'weekend':''} ${i===0&&view.calendarOffset===0?'today':''}"><span class="date-number">${d.getDate()}</span><span class="date-day">${d.toLocaleDateString('ru-RU',{weekday:'short'})}</span></th>`).join('')}</tr></thead><tbody>${rooms.filter(r=>view.calendarFilter==='all'||view.calendarFilter===r.id).map(r=>{const ri=h.rooms.indexOf(r);return `<tr class="room-group"><td>${esc(r.name)}<small>Доступно номеров · общий остаток</small></td>${dates.map((_,di)=>`<td>${h.stale||!h.connected?'—':cellData(ri,di,30).inventory}</td>`).join('')}</tr>${rows.map(({d,bb,role})=>`<tr data-rate-row="${d}-${bb?'bb':'ro'}"><td class="rate-label"><strong>Hopinn ${d}%</strong><small>${bb?'С завтраком':'Без завтрака'}</small></td>${dates.map((date,di)=>{const c=cellData(ri,di,d,bb),key=`${ri}:${di}:${d}:${bb?1:0}`,label=c.unsupported?'Размещение недоступно':c.stale?'Нет данных':c.closed?c.noStock?'Нет мест':'Закрыт':money(c.guest);return `<td><button class="calendar-cell ${c.closed||c.stale||c.unsupported?'closed':''}" data-cell="${key}" data-action="cell:${key}" aria-label="${esc(r.name)}, ${date.toLocaleDateString('ru-RU')}, ${role}, ${label}"><span>${label}</span>${!c.closed&&!c.stale&&!c.unsupported&&bb?`<small class="breakfast-price">В том числе завтраки<br>${money(c.guestBreakfast)}</small>`:''}${!c.closed&&!c.stale&&!c.unsupported&&c.minLos>1?'<i class="limited"></i>':''}</button></td>`;}).join('')}</tr>`).join('')}`;}).join('')}</tbody></table></div>${!rooms.length?`<div class="mt">${note('Пока нет участвующих сопоставленных категорий. Завершите настройку в разделе «Номера и тарифы».','warning')}</div>`:''}<div class="calendar-legend"><span><i class="legend-dot"></i>Есть ограничение</span><span>${icon('MoveHorizontal',13)} Наведите или нажмите на цену</span><span>Все суммы за номер за ночь</span></div><div class="between mt"><p class="tiny muted">Обновлено: ${esc(h.updated)}</p><span class="not-editable">${icon('Eye',13)}Только просмотр</span></div><div class="mt">${note('Цена для клиента уже включает сервисный сбор и завтрак, если он выбран в тарифе. В деталях — гостиничная часть до агентского вознаграждения. Ограничение «от 2 ночей» не означает отсутствие номеров.')}</div>`;
}
function cellDetail(key){const [ri,di,d,b]=key.split(':').map(Number),c=cellData(ri,di,d,!!b),r=hotel().rooms[ri];return `<h3>${dateAt(di).toLocaleDateString('ru-RU',{day:'numeric',month:'long'})} · Hopinn ${d}%</h3><p class="tiny muted mb">${esc(r.name)} · ${c.adults} ${c.adults===1?'взрослый':'взрослых'}, ${b?'с завтраком':'без завтрака'}</p>${c.unsupported?note('Категория не поддерживает выбранное число взрослых на основных местах. Выберите другое количество гостей. Остаток номеров от этого не становится нулевым.','warning'):c.stale?note('Актуальные данные ещё не получены. Остаток и цена неизвестны.','warning'):c.closed?note(c.noStock?'Свободных номеров нет. Отель может оставаться активным.':'Этот вариант тарифа закрыт на дату. Другой вариант питания может быть доступен.'):`<div class="read-value"><span>Основной тариф без завтрака</span><strong>${money(c.base)}</strong></div><div class="read-value"><span>Скидка гостю на проживание</span><strong>${d}%</strong></div><div class="read-value"><span>Цена гостю ${b?'с завтраками':''}</span><strong>${money(c.guest)}</strong></div>${b?`<div class="read-value"><span>В том числе завтраки, гостю</span><strong>${money(c.guestBreakfast)}</strong></div>`:''}<div class="read-value"><span>Полная скидка отеля на проживание</span><strong>${c.full.toLocaleString('ru-RU')}%</strong></div><div class="read-value"><span>Отелю после сервисного сбора ${hotel().serviceFee??13}%</span><strong>${money(c.hotel)}</strong></div>${b?`<div class="read-value"><span>В том числе завтраки, отелю</span><strong>${money(c.hotelBreakfast)}</strong></div>`:''}<p class="tiny muted mt-sm">Агентское вознаграждение не вычтено</p><div class="read-value"><span>Ограничения</span><strong>${c.minLos>1?'От '+c.minLos+' ночей':'Не получены'}</strong></div>`}`;}
function profilePage(){return head('Мой профиль','Личный аккаунт для доступа к вашим отелям.',btn('Выйти','logout','outline','LogOut'))+`<div class="form-layout"><form id="profile-form" class="card"><div class="flex mb"><div class="avatar" style="width:52px;height:52px;font-size:15px">АВ</div><div><h2>${esc(state.user.name)}</h2><p class="card-subtitle">${esc(state.role)} · ${esc(hotel().name)}</p></div></div><div class="form-grid">${field('Имя и фамилия','name',state.user.name,{required:true,full:true})}${field('Email для входа','email',state.user.email,{disabled:true,full:true,hint:'Смена email требует подтверждения старого и нового адреса.'})}${field('Телефон','phone',state.user.phone,{type:'tel',full:true})}</div><div class="form-footer">${btn('Изменить email','change-email','outline')}<button class="btn primary" type="submit">Сохранить</button></div></form><aside class="help-card">${icon('CircleUserRound',22)}<h3>Один аккаунт для всех отелей</h3><p>Имя и телефон относятся к вашему аккаунту. Роль и права определяются отдельно для каждого отеля.</p></aside></div>`;}
function outOfScope(route){const booking=route==='bookings';return head(booking?'Бронирования':'Акты и сверки',booking?'Здесь будет работа с бронированиями гостей.':'Здесь будут документы и взаиморасчёты с Hopinn.')+`<section class="card empty-state"><div class="empty-icon">${icon(booking?'CalendarCheck':'FileText',32)}</div><h2>Этот раздел — следующий этап</h2><p>В текущем прототипе показаны структура экстранета и подготовка отеля к запуску. Работа с ${booking?'бронированиями':'актами и сверками'} будет описана отдельно.</p>${btn('Вернуться к отелю','go:overview','outline','ArrowLeft')}</section>`;}
function showToast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
function modal(title,subtitle,body,actions='',wide=false){hideTooltip();modalReturn=document.activeElement;$('#overlay').innerHTML=`<div class="modal-backdrop" data-backdrop><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><h2 id="modal-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="icon-btn" data-action="close" aria-label="Закрыть окно">${icon('X',20)}</button></div>${body}${actions?`<div class="modal-actions">${actions}</div>`:''}</section></div>`;document.body.classList.add('no-scroll');setTimeout(()=>$('#overlay button, #overlay input, #overlay select')?.focus(),10);}
function closeOverlay(){const had=$('#overlay').innerHTML;$('#overlay').innerHTML='';document.body.classList.remove('no-scroll');if(had&&modalReturn?.isConnected)modalReturn.focus();}
function demoModal(){modal('Сценарии прототипа','Пульт демонстрации. Эти действия не доступны отелю в рабочем кабинете.',`<div class="scenario-grid">${[['unconnected','Первый вход','Формы закрыты до первого получения данных','PlugZap'],['setup','Подготовка данных','Заполните сайт и сопоставьте категорию','LayoutDashboard'],['review','На модерации','БО проверяет данные и готовит контент','Clock3'],['fixes','Нужны исправления','Замечания бэкофиса','CircleAlert'],['active','Отель активен','Контент и предложения готовы','CircleCheck'],['empty','Активен без фонда','Фонд закрыт в TL, допуск сохраняется','CalendarDays'],['paused','Приостановлен','Ошибка цены, возобновляет БО','CirclePause'],['nobreakfast','Без завтраков','Три специальных тарифа','Coffee'],['missingrating','Без рейтинга','Нет достоверных оценок и отзывов','Star']].map(([id,title,desc,ic])=>`<button class="scenario" data-action="scenario:${id}">${icon(ic,21)}<div><h3>${title}</h3><p>${desc}</p></div></button>`).join('')}</div><div class="grid-two mt"><div class="field"><label for="demo-role">Роль сотрудника</label><select id="demo-role"><option ${roleAdmin()?'selected':''}>Администратор</option><option ${!roleAdmin()?'selected':''}>Сотрудник</option></select></div><div class="field"><label for="demo-connection">Обмен с TL после первого подключения</label><select id="demo-connection"><option value="ok" ${hotel().connected&&!hotel().stale?'selected':''}>Данные получены</option><option value="stale" ${hotel().stale?'selected':''}>Данные устарели</option><option value="none" ${!hotel().connected?'selected':''}>Связь недоступна</option></select></div></div><div class="mt">${btn('Показать проверку готовности БО','demo-readiness','outline','ShieldCheck')}</div><p class="tiny muted mt">Все сведения вымышлены. Письма не отправляются, действия в TravelLine не выполняются. Активация и проверка БО здесь имитируются.</p>`,btn('Сбросить демоданные','reset','ghost small','RefreshCw')+btn('Применить настройки','demo-apply','primary','Check'),true);}
function roomModal(id){const r=hotel().rooms.find(r=>r.id===id);modal('Категория номера',r.name,`<form id="room-form" data-id="${id}"><label class="check-label mb"><input type="checkbox" name="participating" ${r.participating!==false?'checked':''}> Предлагать эту категорию в Hopinn</label><div class="mapping-grid"><div class="mapping-source"><div class="section-label">TravelLine · ID ${r.id}</div><strong class="mt-sm">${esc(r.name)}</strong><p>${r.area??'Не указано'} м²</p><p>${esc(r.beds||'Не указано')}</p></div><div class="mapping-arrow">${icon('ArrowRight',22)}</div><div class="stack-sm">${field('Класс номера Hopinn','roomClass',r.class,{select:['',...CLASS_LIST]})}${field('Тип основных кроватей','roomBed',r.bed,{select:['',...BED_LIST]})}</div></div><section class="mt"><h3>Вместимость и размещение</h3><p class="tiny muted mt-sm">Получено из TL · только просмотр</p><div class="read-value"><span>Основные / дополнительные места</span><strong>${r.main??'Не указано'} / ${r.extra??'Не указано'}</strong></div><div class="read-value"><span>Взрослые на основных местах</span><strong>${esc((r.adultOptions||[]).join(', ')||'Не указано')}</strong></div><div class="read-value"><span>Дети: возраст и размещение</span><strong>${esc(r.children||'Не указано')}</strong></div><p class="tiny muted mt-sm">Допустимость и цена зависят от предложения TL. Ребёнок без места не обязательно размещается бесплатно. Дополнительное место не подтверждает конкретный диван или детскую кроватку.</p></section><div id="room-error" class="error-text mt-sm"></div><div class="modal-actions">${btn('Отмена','close','outline')}<button class="btn primary" type="submit">Сохранить</button></div></form>`,'',true);$('#room-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),cl=String(f.get('roomClass')),bed=String(f.get('roomBed')),participating=f.has('participating');if(participating&&(!cl||!bed)){$('#room-error').textContent='Выберите класс и тип кроватей для участвующей категории.';return;}if(participating&&['Две односпальные','Одна большая кровать'].includes(r.beds)&&bed!==r.beds){$('#room-error').textContent='Тип кроватей не соответствует данным TL.';return;}r.class=cl;r.bed=bed;r.participating=participating;invalidateChecks('rooms');scheduleDemoChecks();saveState();closeOverlay();render();showToast('Сопоставление сохранено. Затронутые проверки ожидают обновления.');});}
function inviteModal(){if(!roleAdmin())return;modal('Пригласить сотрудника','Доступ будет предоставлен к выбранному отелю.',`<form id="invite-form"><div class="form-grid">${field('Имя и фамилия','inviteName','',{required:true,full:true})}${field('Email','inviteEmail','',{type:'email',required:true,full:true})}${field('Должность','inviteJob','',{})}${field('Роль','inviteRole','Сотрудник',{select:['Сотрудник','Администратор']})}</div><div class="note mt">${icon('Info',17)}<div>Демонстрация: приглашение появится в списке, письмо не отправляется.</div></div><div id="invite-error" class="error-text mt-sm"></div><div class="modal-actions">${btn('Отмена','close','outline')}<button type="submit" class="btn primary">Пригласить</button></div></form>`);$('#invite-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),email=String(f.get('inviteEmail')).trim();if(hotel().staff.some(x=>x.email.toLowerCase()===email.toLowerCase()&&x.status!=='Доступ отозван')){$('#invite-error').textContent='Этот сотрудник уже есть в списке отеля.';return;}hotel().staff.push({id:Date.now(),name:String(f.get('inviteName')).trim(),email,job:f.get('inviteJob'),role:f.get('inviteRole'),status:'Приглашён',last:'Ещё не входил'});saveState();closeOverlay();render();showToast('Демонстрационное приглашение добавлено. Письмо не отправлялось.');});}
function staffModal(id){if(!roleAdmin())return;const u=hotel().staff.find(x=>String(x.id)===id);const last=u.role==='Администратор'&&u.status==='Активен'&&hotel().staff.filter(x=>x.role==='Администратор'&&x.status==='Активен').length===1;modal('Доступ сотрудника',esc(u.name)+' · '+esc(u.email),`<div class="field"><label for="staff-role">Роль</label><select id="staff-role" ${last?'disabled':''}><option ${u.role==='Сотрудник'?'selected':''}>Сотрудник</option><option ${u.role==='Администратор'?'selected':''}>Администратор</option></select></div><div class="mt">${badge(esc(u.status),u.status==='Активен'?'good':'pending')}</div>${last?`<div class="mt">${note('Это последний действующий администратор. Сначала пригласите замену и дождитесь принятия приглашения.','warning','ShieldCheck')}</div>`:''}`,`${u.status==='Приглашён'?btn('Повторить приглашение','resend:'+id,'outline small','Mail'):''}${btn('Отозвать доступ','revoke:'+id,'danger small','',last?'disabled':'')}${btn('Сохранить роль','staff-save:'+id,'primary')}`);}
function notifications(){modalReturn=document.activeElement;$('#overlay').innerHTML=`<aside class="notification-panel" role="dialog" aria-modal="false" aria-label="Уведомления"><div class="between"><h2 style="font-size:18px">Уведомления</h2><button class="icon-btn" data-action="close" aria-label="Закрыть уведомления">${icon('X',18)}</button></div><div class="between mt-sm"><span class="tiny muted">${esc(hotel().name)}</span><button class="text-link tiny" data-action="read-all">Прочитать все</button></div>${hotel().notifications.map(n=>`<button class="notification ${!n.read?'unread':''}" data-action="notification:${n.id}"><h3>${esc(n.title)}</h3><p>${esc(n.text)}</p><small>${esc(n.when)}</small></button>`).join('')}</aside>`;}
function submitReview(){const checks=getChecks(),missing=checks.filter(c=>!c.done);if(missing.length){modal('Завершите подготовку','Отправить данные можно после обязательных шагов.',`<div class="status-list">${missing.map(c=>`<button class="status-item text-link" style="text-align:left" data-action="go:${c.route}">${icon('CircleAlert',18)}${c.name}${icon('ArrowRight',16)}</button>`).join('')}</div>`,btn('Продолжить настройку','continue','primary'));return;}modal('Отправить отель на модерацию','Все обязательные данные и сопоставления готовы.',`<div class="stack-sm">${note('Бэкофис проверит сведения и настройки, подготовит скетчи и описание. Об активации сообщим в кабинете и по email.','', 'ShieldCheck')}<p class="tiny muted">Во время проверки вы можете продолжать исправлять данные. Бэкофис увидит изменения.</p></div>`,btn('Пока не отправлять','close','outline')+btn('Отправить на модерацию','confirm-review','primary','Send'));}
function tlPhotosModal(){if(!canEdit())return;modal('Фотографии из TravelLine','Выберите фотографии номеров самой простой или следующей категории.',`<div class="photo-grid">${[0,1,2].map(i=>`<label class="photo-card" style="cursor:pointer"><div class="photo">${art(i)}</div><div class="photo-info"><div class="flex"><input type="checkbox" name="tl-photo" value="${i}" ${hotel().photos.some(p=>p.kind==='room'&&p.source==='TravelLine'&&p.asset===i)?'checked':''}><strong>${['Стандарт Double','Стандарт Twin','Улучшенный Double'][i]}</strong></div></div></label>`).join('')}</div><p class="tiny muted mt">Выбранные фото не нужно загружать повторно. Остальные изображения, загруженные вами, сохранятся.</p>`,btn('Отмена','close','outline')+btn('Сохранить выбор','save-tl-photos','primary'),true);}
function bindLocal(){
 $('#hotel-switch')?.addEventListener('change',e=>{state.hotelId=e.target.value;view.photoIndex=0;view.calendarFilter='all';saveState();render();showToast('Выбран отель «'+hotel().name+'».');});
 $('#compare-range')?.addEventListener('input',e=>e.target.closest('.compare').style.setProperty('--split',e.target.value+'%'));
 $('#calendar-adults')?.addEventListener('change',e=>{view.calendarAdults=Number(e.target.value);render();});
 updateConditionalFields();
 $('#services-form')?.addEventListener('change',updateConditionalFields);
 $('#f-reception')?.addEventListener('change',updateConditionalFields);
 $('#f-deposit')?.addEventListener('change',updateConditionalFields);
 $('#calendar-filter')?.addEventListener('change',e=>{view.calendarFilter=e.target.value;render();});
 $('#preview-bed')?.addEventListener('change',e=>{const twin=e.target.value==='Две односпальные';$('#preview-room-price').textContent=money(twin?6240:6000)+' / ночь';showToast(twin?'Выбран вариант Twin.':'Выбран вариант Double.');});
 $('#general-form')?.addEventListener('submit',e=>{e.preventDefault();const form=e.target;let valid=true;$$('.field.invalid').forEach(x=>x.classList.remove('invalid'));$$('.error-text').forEach(x=>{x.hidden=true;x.textContent='';});for(const input of form.querySelectorAll('input[required],select[required],textarea[required]')){if(input.disabled||input.closest('[hidden]'))continue;let message='';if(!input.value.trim())message='Заполните обязательное поле.';else if(input.type==='email'&&!/.+@.+\..+/.test(input.value))message='Укажите адрес электронной почты.';else if(input.name==='website'&&!/^https?:\/\/.+\..+/.test(input.value))message='Укажите сайт в виде https://hotel.example.';if(message){valid=false;const wrap=input.closest('.field');wrap.classList.add('invalid');wrap.querySelector('.error-text').textContent=message;wrap.querySelector('.error-text').hidden=false;}}
 if(!valid){form.querySelector('.invalid input')?.focus();showToast('Проверьте обязательные поля.');return;}const data=new FormData(form),changed=[...data.entries()].filter(([k,v])=>hotel().form[k]!==String(v).trim()).map(([k])=>k);for(const[k,v]of data.entries())hotel().form[k]=String(v).trim();hotel().name=hotel().form.name;if(changed.length){invalidateChecks(changed.every(k=>k==='website')?'website':'general');scheduleDemoChecks();}saveState();render();showToast(hotel().stage==='review'?'Изменения сохранены. Бэкофис увидит обновлённые данные.':'Сведения об отеле сохранены.');});
 $('#services-form')?.addEventListener('submit',e=>{e.preventDefault();if(!canEdit())return;const f=new FormData(e.target);for(const[id]of SERVICE_LIST){hotel().services[id]=id==='parking'?(f.has('parking-free')&&f.has('parking-paid')?'Бесплатно и платно':f.has('parking-free')?'Бесплатно':f.has('parking-paid')?'Платно':'Нет'):f.has('service-'+id)?(f.has('paid-'+id)?'Платно':'Бесплатно'):'Нет';}hotel().serviceTimes={early:String(f.get('early-time')||''),late:String(f.get('late-time')||'')};invalidateChecks('services');scheduleDemoChecks();saveState();render();showToast('Услуги сохранены.');});
 $('#rates-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),roles=hotel().rates.map(r=>String(f.get('rate-'+r.id)));if(!requiredRateRoles().every(x=>roles.filter(r=>r===x).length===1)){$('#rates-error').textContent='Назначьте каждую обязательную роль ровно одному тарифу.';return;}hotel().rates.forEach((r,i)=>r.role=roles[i]);invalidateChecks('rates');scheduleDemoChecks();saveState();render();showToast('Назначения тарифов сохранены.');});
 $('#profile-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);state.user.name=String(f.get('name')).trim();state.user.phone=String(f.get('phone')).trim();saveState();render();showToast('Профиль сохранён.');});
 $('#photo-file')?.addEventListener('change',async e=>{if(!canEdit())return;const targetHotel=hotel();const kind=e.target.dataset.kind||'room',limit=kind==='room'?5:3,replaceId=e.target.dataset.replaceId,available=replaceId?1:limit-targetHotel.photos.filter(p=>p.kind===kind).length;const files=Array.from(e.target.files).slice(0,available);let added=0;for(const file of files){if(!file.type.startsWith('image/'))continue;if(file.size>1500000){showToast('Для локальной демонстрации выберите изображение до 1,5 МБ.');continue;}const url=await new Promise(resolve=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>resolve(null);reader.readAsDataURL(file);});if(!url)continue;const item={id:replaceId||'upload-'+Date.now()+'-'+added,kind,asset:0,name:file.name.replace(/\.[^.]+$/,''),source:'Загружено вами',url};if(replaceId){const i=targetHotel.photos.findIndex(p=>p.id===replaceId);targetHotel.photos[i]=item;}else targetHotel.photos.push(item);added++;}if(added){invalidateChecks('photos',targetHotel);scheduleDemoChecks(targetHotel);const persisted=saveState();render();showToast(persisted?'Фотографии добавлены.':'Фото добавлены на текущий сеанс. В хранилище браузера недостаточно места.');}});
 $$('[data-cell]').forEach(el=>{el.addEventListener('mouseenter',()=>{if(matchMedia('(hover:hover)').matches)tooltipTimer=setTimeout(()=>showTooltip(el),220);});el.addEventListener('mouseleave',hideTooltip);el.addEventListener('focus',()=>showTooltip(el));el.addEventListener('blur',hideTooltip);});
}
function showTooltip(el){hideTooltip();const tip=document.createElement('div');tip.className='cell-tooltip';tip.id='cell-tooltip';tip.setAttribute('role','tooltip');tip.innerHTML=cellDetail(el.dataset.cell);document.body.appendChild(tip);const r=el.getBoundingClientRect(),height=tip.getBoundingClientRect().height;let left=r.left+r.width/2-170;left=Math.min(innerWidth-350,Math.max(10,left));let top=r.bottom+10;if(top+height>innerHeight-12)top=Math.max(10,r.top-height-10);tip.style.left=left+'px';tip.style.top=top+'px';}
function hideTooltip(){clearTimeout(tooltipTimer);$('#cell-tooltip')?.remove();}
document.addEventListener('click',e=>{if(e.target.closest('.skip-link')){e.preventDefault();$('#main').focus({preventScroll:true});$('#main').scrollIntoView({block:'start',behavior:'instant'});return;}const el=e.target.closest('[data-action]');if(el){const action=el.dataset.action;handle(action,el);}else if(e.target.matches('[data-backdrop]'))closeOverlay();else if($('#overlay .notification-panel')&&!e.target.closest('.notification-panel'))closeOverlay();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeOverlay();hideTooltip();if(view.mobile){view.mobile=false;render();}}if(e.key==='Enter'&&e.target.matches('[data-action][role="link"]'))handle(e.target.dataset.action,e.target);const m=$('#overlay .modal');if(e.key==='Tab'&&m){const focusable=Array.from(m.querySelectorAll('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),textarea:not(:disabled)')).filter(x=>x.offsetParent!==null);const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('scroll',hideTooltip,true);
function handle(action,el){
 if(action.startsWith('go:')){go(action.slice(3));return;}
 const [name,...parts]=action.split(':'),arg=parts.join(':');
 if(name==='close'){closeOverlay();return;}
 if(name==='mobile'){view.mobile=true;render();return;}
 if(name==='mobile-close'){view.mobile=false;render();return;}
 if(name==='profile'){go('profile');return;}
 if(name==='notifications'){if($('#overlay .notification-panel'))closeOverlay();else notifications();return;}
 if(name==='notification'){const n=hotel().notifications.find(x=>String(x.id)===arg);n.read=true;saveState();go(n.route);return;}
 if(name==='read-all'){hotel().notifications.forEach(x=>x.read=true);saveState();render();notifications();return;}
 if(name==='demo-readiness'){refreshDemoChecks();saveState();const checks=getAutoChecks();modal('Готовность к активации · действие БО','Демонстрация результата проверки, без автоматической активации.',`<div class="status-list">${checks.map(c=>`<div class="status-item"><span>${esc(c.name)}</span>${badge(c.status,c.status==='Проверено'?'good':c.status==='Есть ошибка'?'error':'pending')}</div>`).join('')}</div><div class="mt">${note('Отдельно БО проверяет действующий договор, условия, ФСА, достоверность сведений и качество контента. Ручные проверки этим действием не подтверждаются.')}</div>`,btn('Закрыть','close','primary'));return;}
 if(name==='demo'){demoModal();return;}
 if(name==='demo-apply'){state.role=$('#demo-role').value;const c=$('#demo-connection').value;hotel().stale=c==='stale';hotel().connected=c!=='none';if(c==='ok'){hotel().firstDataReceived=true;refreshDemoChecks();}saveState();closeOverlay();render();showToast('Демонстрационные настройки применены.');return;}
 if(name==='scenario'){applyScenario(arg);saveState();go('overview');showToast('Сценарий переключён. Это действие пульта демонстрации.');return;}
 if(name==='reset'){modal('Сбросить демонстрацию?','Будут сброшены только изменения в этом прототипе.',`<p class="tiny muted">Оба демонстрационных отеля вернутся к исходному состоянию. Реальные данные и системы не затрагиваются.</p>`,btn('Отмена','close','outline')+btn('Сбросить','reset-confirm','primary'));return;}
 if(name==='reset-confirm'){state=createState();saveState();go('overview');showToast('Демонстрация начата заново.');return;}
 if(name==='continue'){const next=getChecks().find(c=>!c.done);go(next?.route||'overview');return;}
 if(name==='submit-review'){submitReview();return;}
 if(name==='confirm-review'){hotel().stage='review';hotel().contentReady=false;notifyHotel('Отель отправлен на модерацию','Бэкофис проверит сведения и подготовит контент.','overview');saveState();go('overview');showToast('Отель отправлен на модерацию.');return;}
 if(name==='connect'){hotel().connected=true;hotel().firstDataReceived=true;hotel().updated='Только что';refreshDemoChecks();saveState();render();showToast('Демонстрация: подключение установлено, данные получены.');return;}
 if(name==='sync'){if(!hotel().connected){showToast('Сначала подключите канал Hopinn в TravelLine.');return;}const targetHotel=hotel();el.disabled=true;const old=el.innerHTML;el.innerHTML=icon('LoaderCircle',17)+' Обновляем';el.querySelector('svg').classList.add('spinner');setTimeout(()=>{targetHotel.updated='Только что';targetHotel.stale=false;refreshDemoChecks(targetHotel);saveState();render();showToast('Демонстрационные данные обновлены.');},650);return;}
 if(name==='support'){modal('Связь с бэкофисом','Встроенной переписки в экстранете нет.',`<p class="muted tiny">Для изменения сведений или решения вопросов напишите на предварительный адрес поддержки:</p><p class="mt"><a href="mailto:hotel_support@hopinn.ru">hotel_support@hopinn.ru</a></p>`,btn('Понятно','close','primary'));return;}
 if(name==='sketch'){view.photoIndex=Number(arg);render();return;}
 if(name==='preview'){view.preview=arg;render();return;}
 if(name==='rotate-sketch'){const n=validSketches().length;if(n>1)view.photoIndex=(view.photoIndex+1+Math.floor(Math.random()*(n-1)))%n;render();showToast('Показан другой скетч с его исходной фотографией.');return;}
 if(name==='replace-photo'){if(!canEdit())return;const p=hotel().photos.find(p=>p.id===arg),input=$('#photo-file');input.dataset.kind=p.kind;input.dataset.replaceId=p.id;input.multiple=false;input.value='';input.click();return;}
 if(name==='upload'){if(!canEdit())return;const input=$('#photo-file');input.dataset.kind=arg;delete input.dataset.replaceId;input.multiple=true;input.value='';input.click();return;}
 if(name==='remove-photo'){if(!canEdit())return;const p=hotel().photos.find(p=>p.id===arg);modal('Удалить фотографию?','Фотография будет убрана из набора этого отеля.',`<div style="height:200px;border-radius:14px;overflow:hidden">${art(p.asset,false,p.url)}</div><p class="tiny muted mt-sm">Для отправки на модерацию нужно сохранить минимум 3 фотографии номеров.</p>`,btn('Отмена','close','outline')+btn('Удалить фотографию','confirm-remove-photo:'+arg,'primary','Trash2'));return;}
 if(name==='confirm-remove-photo'){if(!canEdit())return;hotel().photos=hotel().photos.filter(p=>p.id!==arg);invalidateChecks('photos');scheduleDemoChecks();saveState();closeOverlay();render();showToast('Фотография удалена из набора.');return;}
 if(name==='tl-photos'){tlPhotosModal();return;}
 if(name==='save-tl-photos'){const selected=$$('input[name="tl-photo"]:checked').map(x=>Number(x.value)),other=hotel().photos.filter(p=>p.source!=='TravelLine'||p.kind!=='room');if(other.filter(p=>p.kind==='room').length+selected.length>5){showToast('Можно выбрать не больше 5 фотографий номеров.');return;}hotel().photos=[...other,...selected.map(i=>({id:hotel().photos.find(p=>p.source==='TravelLine'&&p.kind==='room'&&p.asset===i)?.id||'tl-'+i,kind:'room',asset:i,name:['Стандарт · большая кровать','Стандарт · две кровати','Улучшенный · интерьер'][i],source:'TravelLine'}))];invalidateChecks('photos');scheduleDemoChecks();saveState();closeOverlay();render();showToast('Выбор фотографий сохранён.');return;}
 if(name==='room-up'||name==='room-down'){const a=hotel().rooms,i=a.findIndex(r=>r.id===arg),j=i+(name==='room-up'?-1:1);if(j>=0&&j<a.length){[a[i],a[j]]=[a[j],a[i]];invalidateChecks('rooms');scheduleDemoChecks();saveState();render();}return;}
 if(name==='room'){roomModal(arg);return;}
 if(name==='calendar-prev'){view.calendarOffset-=10;render();return;}
 if(name==='calendar-next'){view.calendarOffset+=10;render();return;}
 if(name==='calendar-today'){view.calendarOffset=0;render();return;}
 if(name==='cell'){modal('Цена и условия','Демонстрационные данные календаря',cellDetail(arg),btn('Закрыть','close','primary'));return;}
 if(name==='legal'){legalModal();return;}
 if(name==='contract'){contractModal(arg);return;}
 if(name==='download-contract'){const old=arg==='old';const text=`ДЕМОНСТРАЦИОННЫЙ ОБРАЗЕЦ. НЕ ЯВЛЯЕТСЯ ДОГОВОРОМ.\n\nHopinn — ООО «Демо Отель»\nНомер: ${old?'HI-2026-0821':'HI-2026-1048'}\nСостояние: ${old?'не действует':'действует'}\nСервисный сбор: ${old?15:13}%\nАгентское вознаграждение: 0,01%\n\nВ рабочем кабинете здесь будет загруженный бэкофисом документ.\nРеальные реквизиты и подписи отсутствуют.`;const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='Демонстрационный-договор-'+(old?'0821':'1048')+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);showToast('Демонстрационный образец скачан.');return;}
 if(name==='invite'){inviteModal();return;}
 if(name==='staff'){staffModal(arg);return;}
 if(['staff-save','revoke','resend'].includes(name)){if(!roleAdmin())return;const u=hotel().staff.find(x=>String(x.id)===arg);if(name==='resend'){closeOverlay();showToast('Демонстрация: приглашение обновлено. Письмо не отправлялось.');return;}const last=u.role==='Администратор'&&u.status==='Активен'&&hotel().staff.filter(x=>x.role==='Администратор'&&x.status==='Активен').length===1;if(name==='revoke'){if(last){showToast('Нельзя отозвать доступ последнего администратора.');return;}u.status='Доступ отозван';}else{const role=$('#staff-role').value;if(last&&role!=='Администратор'){showToast('Нельзя изменить роль последнего администратора.');return;}u.role=role;}saveState();closeOverlay();render();showToast('Доступ сотрудника обновлён.');return;}
 if(name==='change-email'){modal('Изменение email','В рабочей версии потребуется подтверждение обоих адресов.',`<div class="field"><label for="new-email">Новый email</label><input id="new-email" type="email" placeholder="name@hotel.example"></div><p class="tiny muted mt">В прототипе письма не отправляются. Подтверждение можно завершить демонстрационно.</p>`,btn('Отмена','close','outline')+btn('Подтвердить в демо','email-confirm','primary'));return;}
 if(name==='email-confirm'){const email=$('#new-email').value.trim();if(!/.+@.+\..+/.test(email)){showToast('Укажите корректный email.');return;}state.user.email=email;saveState();closeOverlay();render();showToast('Демонстрация: email изменён. Реальное подтверждение не выполнялось.');return;}
 if(name==='logout'){modal('Выход из экстранета','Демонстрация завершения сеанса.',`<p class="tiny muted">Изменения прототипа сохранены в этом браузере. Можно вернуться в кабинет или начать заново.</p>`,btn('Начать заново','reset','outline')+btn('Вернуться в кабинет','close','primary'));return;}
}
function scheduleDemoChecks(h=hotel()){setTimeout(()=>{refreshDemoChecks(h);saveState();if(hotel().id===h.id&&view.route==='connection'&&!$('#overlay').innerHTML)render();},900);}
function updateConditionalFields(){
 const reception=$('#f-reception')?.value,deposit=$('#f-deposit')?.value;
 $$('[data-condition="reception-hours"]').forEach(el=>{el.hidden=reception==='Круглосуточно';el.querySelectorAll('input,textarea,select').forEach(x=>x.required=!el.hidden);});
 $$('[data-condition="deposit"]').forEach(el=>el.hidden=deposit!=='Требуется');
 $$('[data-condition="pets"]').forEach(el=>el.hidden=hotel().services.pets==='Нет');
 for(const[id]of SERVICE_LIST){const enabled=$(`[name="service-${id}"]`);if(!enabled)continue;$$(`[data-service-paid="${id}"]`).forEach(el=>{el.disabled=!enabled.checked||!canEdit();});$$(`[data-service-time="${id}"]`).forEach(el=>{el.hidden=!enabled.checked;el.querySelectorAll('input').forEach(x=>x.disabled=!enabled.checked||!canEdit());});}
}
render();
